import{_ as e,a0 as a,w as r,s as x,ao as s,I as l,x as t,a1 as o,A as u}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const g=JSON.parse('{"title":"好奇 Linux？试试云端的 Linux 桌面 | LCTT x X-CMD","titleTemplate":false,"description":"好奇 Linux？试试云端的 Linux 桌面 | LCTT (201511) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"好奇 Linux？试试云端的 Linux 桌面 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"好奇 Linux？试试云端的 Linux 桌面 | LCTT (201511) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201511/20151012 Curious about Linux Try Linux Desktop on the Cloud","title":"好奇 Linux？试试云端的 Linux 桌面","tag":"201511","desc":""},"relativePath":"201511/20151012 Curious about Linux Try Linux Desktop on the Cloud.md","filePath":"[post].md"}'),p={name:"201511/20151012 Curious about Linux Try Linux Desktop on the Cloud.md"};function L(d,n,w,C,m,b){const i=a("Link");return r(),x("div",null,[n[14]||(n[14]=s('<h1 id="好奇-linux-试试云端的-linux-桌面" tabindex="-1">好奇 Linux？试试云端的 Linux 桌面 <a class="header-anchor" href="#好奇-linux-试试云端的-linux-桌面" aria-label="Permalink to “好奇 Linux？试试云端的 Linux 桌面”">​</a></h1><p>Linux 在桌面操作系统市场上只占据了非常小的份额，从目前的调查结果来看，估计只有2%的市场份额；对比来看，丰富多变的 Windows 系统占据了接近90%的市场份额。对于 Linux 来说，要挑战 Windows 在桌面操作系统市场的垄断，需要有一个让用户学习不同的操作系统的简单方式。如果你相信传统的 Windows 用户会再买一台机器来使用 Linux，那你就太天真了。我们只能去试想用户重新分区，设置引导程序来使用双系统，或者跳过所有步骤回到一个最简单的方法。</p><p><img src="http://www.linuxlinks.com/portal/content/reviews/Cloud/CloudComputing.png" alt=""></p><p>我们实验过一系列让用户试操作 Linux 的无风险的使用方法，不涉及任何分区管理，包括 CD/DVD 光盘、USB 存储棒和桌面虚拟化软件等等。通过实验，我强烈推荐使用 VMware 的 VMware Player 或者 Oracle VirtualBox 虚拟机，对于桌面操作系统或者便携式电脑的用户，这是一种安装运行多操作系统的相对简单而且免费的的方法。每一台虚拟机和其他虚拟机相隔离，但是共享 CPU、内存、网络接口等等。虚拟机仍需要一定的资源来安装运行 Linux，也需要一台相当强劲的主机。但对于一个好奇心不大的人，这样做实在是太麻烦了。</p><p>要打破用户传统的使用观念是非常困难的。很多 Windows 用户可以尝试使用 Linux 提供的自由软件，但也有太多要学习的 Linux 系统知识。这会花掉他们相当一部分时间才能习惯 Linux 的工作方式。</p><p>当然了，对于一个第一次在 Linux 上操作的新手，有没有一个更高效的方法呢？答案是肯定的，接着往下看看云实验平台。</p><h3 id="labxnow" tabindex="-1">LabxNow <a class="header-anchor" href="#labxnow" aria-label="Permalink to “LabxNow”">​</a></h3><p><img src="http://www.linuxlinks.com/portal/content/reviews/Cloud/Screenshot-LabxNow.png" alt="LabxNow"></p><p>LabxNow 提供了一个免费服务，方便广大用户通过浏览器来访问远程 Linux 桌面。开发者将其加强为一个用户个人远程实验室（用户可以在系统里运行、开发任何程序），用户可以在任何地方通过互联网登入远程实验室。</p><p>这项服务现在可以为个人用户提供2核处理器，4GB RAM和10GB的固态硬盘，运行在128G RAM的4 AMD 6272处理器上。</p><h4 id="配置参数" tabindex="-1">配置参数: <a class="header-anchor" href="#配置参数" aria-label="Permalink to “配置参数:”">​</a></h4><ul><li>系统镜像：基于 Ubuntu 14.04 的 Xface 4.10，RHEL 6.5，CentOS(Gnome桌面)，Oracle</li><li>硬件: CPU - 1核或者2核；内存: 512MB, 1GB, 2GB or 4GB</li><li>超快的网络数据传输</li><li>可以运行在所有流行的浏览器上</li><li>可以安装任意程序，可以运行任何程序 – 这是一个非常棒的方法，可以随意做实验学习你想学的任何知识，没有 一点风险</li><li>添加、删除、管理、制定虚拟机非常方便</li><li>支持虚拟机共享，远程桌面</li></ul>',12)),l("p",null,[n[1]||(n[1]=t("你所需要的只是一台有稳定网络的设备。不用担心虚拟专用系统（VPS）、域名、或者硬件带来的高费用。LabxNow提供了一个在 Ubuntu、RHEL 和 CentOS 上实验的非常好的方法。它给 Windows 用户提供一个极好的环境，让他们探索美妙的 Linux 世界。说得深入一点，它可以让用户随时随地在里面工作，而没有了要在每台设备上安装 Linux 的压力。点击下面这个链接进入 ",-1)),o(i,{href:"https://www.labxnow.org/labxweb/"},{default:u(()=>[...n[0]||(n[0]=[t("www.labxnow.org/labxweb/",-1)])]),_:1}),n[2]||(n[2]=t("。",-1))]),n[15]||(n[15]=l("p",null,"另外还有一些其它服务（大部分是收费服务）可以让用户使用 Linux，包括 Cloudsigma 环境的7天使用权和Icebergs.io （通过HTML5实现root权限）。但是现在，我推荐 LabxNow。",-1)),n[16]||(n[16]=l("hr",null,null,-1)),l("p",null,[n[4]||(n[4]=t("来自: ",-1)),o(i,{href:"http://www.linuxlinks.com/article/20151003095334682/LinuxCloud.html"},{default:u(()=>[...n[3]||(n[3]=[t("http://www.linuxlinks.com/article/20151003095334682/LinuxCloud.html",-1)])]),_:1})]),l("p",null,[n[7]||(n[7]=t("译者：",-1)),o(i,{href:"https://github.com/sevenot"},{default:u(()=>[...n[5]||(n[5]=[t("sevenot",-1)])]),_:1}),n[8]||(n[8]=t(" 校对：",-1)),o(i,{href:"https://github.com/wxy"},{default:u(()=>[...n[6]||(n[6]=[t("wxy",-1)])]),_:1})]),l("p",null,[n[11]||(n[11]=t("本文由 ",-1)),o(i,{href:"https://github.com/LCTT/TranslateProject"},{default:u(()=>[...n[9]||(n[9]=[t("LCTT",-1)])]),_:1}),n[12]||(n[12]=t(" 原创编译，",-1)),o(i,{href:"https://linux.cn/"},{default:u(()=>[...n[10]||(n[10]=[t("Linux中国",-1)])]),_:1}),n[13]||(n[13]=t(" 荣誉推出",-1))])])}const k=e(p,[["render",L]]);export{g as __pageData,k as default};
